begin;
select plan(25);
insert into auth.users(id,email) values
 ('11111111-1111-4111-8111-111111111111','title-owner@example.test'),
 ('22222222-2222-4222-8222-222222222222','title-other@example.test');
select public.get_or_create_account_profile('11111111-1111-4111-8111-111111111111','title-owner@example.test',true);
select public.get_or_create_account_profile('22222222-2222-4222-8222-222222222222','title-other@example.test',true);
create temporary table item as select * from public.paste_item_content('11111111-1111-4111-8111-111111111111',repeat('Complete source text. ',30));
create temporary table job as select * from public.claim_processing_job('11111111-1111-4111-8111-111111111111');
create temporary table analysis_call as select r.* from job j cross join lateral public.reserve_analysis(j.user_id,j.id,j.lease_token,0.15) r;
select is((select count(*)::int from job j cross join analysis_call r cross join lateral public.record_model_result(j.user_id,j.id,gen_random_uuid(),r.id,'{"title":"Wrong stale title"}',null)),0,'stale lease cannot save a title');
select is((select title from public.items where id=(select id from item)),'Pasted content','stale title did not change item');
select public.record_model_result(j.user_id,j.id,j.lease_token,r.id,'{"title":"Local language models","failure_reason":"invalid_citation"}','gen-title-analysis') from job j cross join analysis_call r;
select public.settle_analysis(user_id,id,0.001) from analysis_call;
select public.set_processing_stage(user_id,id,lease_token,'invalid_model_output','failed') from job;
select is((select title from public.items where id=(select id from item)),'Local language models','title survives invalid assessment');
select is((select status::text from public.items where id=(select id from item)),'failed','title does not imply a successful assessment');
select is((select count(*)::int from public.assessments),0,'invalid assessment never creates a summary');
select is((select count(*)::int from public.reserve_item_title('11111111-1111-4111-8111-111111111111',(select id from item),0.15)),0,'meaningful title is preserved without another call');

update public.items set title='Pasted content',status='completed' where id=(select id from item);
update public.jobs set status='completed' where id=(select id from job);
select is((select count(*)::int from public.reserve_item_title('22222222-2222-4222-8222-222222222222',(select id from item),0.15)),0,'foreign owner cannot reserve title generation');
select public.set_user_budget('11111111-1111-4111-8111-111111111111',0);
select is((select count(*)::int from public.reserve_item_title('11111111-1111-4111-8111-111111111111',(select id from item),0.15)),0,'zero budget blocks title generation');
select public.set_user_budget('11111111-1111-4111-8111-111111111111',10);
update public.items set expires_at=now()-interval '1 second' where id=(select id from item);
select is((select count(*)::int from public.reserve_item_title('11111111-1111-4111-8111-111111111111',(select id from item),0.15)),0,'expired content cannot be titled');
update public.items set expires_at=now()+interval '1 day' where id=(select id from item);
update public.account_profiles set status='rejected' where user_id='11111111-1111-4111-8111-111111111111';
select is((select count(*)::int from public.reserve_item_title('11111111-1111-4111-8111-111111111111',(select id from item),0.15)),0,'rejected account cannot generate titles');
update public.account_profiles set status='approved' where user_id='11111111-1111-4111-8111-111111111111';
update public.source_contents set content='partial' where item_id=(select id from item);
select is((select count(*)::int from public.reserve_item_title('11111111-1111-4111-8111-111111111111',(select id from item),0.15)),0,'partial saved text cannot start a model call');
update public.source_contents set content=repeat('Complete source text. ',30) where item_id=(select id from item);
create temporary table title_call as select * from public.reserve_item_title('11111111-1111-4111-8111-111111111111',(select id from item),0.15);
select is((select count(*)::int from title_call),1,'existing ready item admits a title-only call');
select is((select text from title_call),repeat('Complete source text. ',30),'only complete saved primary text is returned');
select is((select count(*)::int from public.reserve_item_title('11111111-1111-4111-8111-111111111111',(select id from item),0.15)),0,'unresolved call blocks repeated admission');
select is((select count(*)::int from public.record_item_title('22222222-2222-4222-8222-222222222222',(select id from item),(select id from title_call),'Foreign title','gen-foreign')),0,'foreign result cannot change title');
select is((select count(*)::int from public.record_item_title('11111111-1111-4111-8111-111111111111',(select id from item),(select id from title_call),E'Bad\nheading',null)),0,'multiline title rejected');
select is((select count(*)::int from public.record_item_title('11111111-1111-4111-8111-111111111111',(select id from item),(select id from title_call),'Choosing local language models','gen-title-backfill')),1,'title-only result updates ready item');
select public.settle_analysis('11111111-1111-4111-8111-111111111111',id,0.0001) from title_call;
select public.settle_analysis('11111111-1111-4111-8111-111111111111',id,0.0001) from title_call;
select is((select spent_usd from public.get_usage_summary('11111111-1111-4111-8111-111111111111')),0.0011::numeric,'actual subcent title cost is settled once');
select is((select status::text from public.items where id=(select id from item)),'completed','title-only backfill preserves ready state');
select is((select count(*)::int from public.assessments),0,'title-only backfill does not create an assessment');
update public.items set title='Pasted content' where id=(select id from item);
create temporary table uncertain_call as select * from public.reserve_item_title('11111111-1111-4111-8111-111111111111',(select id from item),0.15);
delete from public.items where id=(select id from item);
select is((select title_item_id from public.usage_reservations where id=(select id from uncertain_call)),null::uuid,'content deletion detaches billing metadata');
select is((select count(*)::int from public.record_item_title('11111111-1111-4111-8111-111111111111',(select id from item),(select id from uncertain_call),'Late title','gen-late-title')),0,'late result cannot resurrect deleted content');
select is((select generation_id from public.usage_reservations where id=(select id from uncertain_call)),'gen-late-title','late generation ID is retained for cost reconciliation');
select is((select reserved_usd from public.get_usage_summary('11111111-1111-4111-8111-111111111111')),0.15::numeric,'unknown charge remains reserved after deletion');
set local role authenticated;
select throws_ok($$select * from public.reserve_item_title('11111111-1111-4111-8111-111111111111',gen_random_uuid(),0.15)$$,'42501',null,'browser cannot bypass confirmation and call budget RPC');
reset role;
select * from finish();
rollback;
